function insert(root, term, freq) {
  let node = root;
  for (const ch of term) {
    node.children[ch] ??= { children: {}, freq: 0 };
    node = node.children[ch];
  }
  node.freq = freq;
}

function findPrefix(root, prefix) {
  let node = root;
  for (const ch of prefix) {
    node = node.children[ch];
    if (!node) return null;
  }
  return node; // O(p) — trivial
}

function suggestNaive(root, prefix, k = 5) {
  const node = findPrefix(root, prefix);
  if (!node) return [];

  const all = [];
  (function walk(n, word) {            // visits EVERY descendant
    if (n.freq > 0) all.push({ word, freq: n.freq });
    for (const [ch, child] of Object.entries(n.children)) walk(child, word + ch);
  })(node, prefix);

  return all.sort((a, b) => b.freq - a.freq).slice(0, k);
}

// prefix 'a' → millions of nodes visited, per keystroke.

// node.top = [{ id, freq }] — precomputed, length k

function suggest(root, prefix) {
  const node = findPrefix(root, prefix);
  return node ? node.top : [];       // O(p), no traversal at all
}

function buildTopK(node, k = 5) {
  const candidates = node.freq > 0 ? [{ id: node.id, freq: node.freq }] : [];

  for (const child of Object.values(node.children)) {
    candidates.push(...buildTopK(child, k)); // children already reduced to k
  }

  node.top = candidates.sort((a, b) => b.freq - a.freq).slice(0, k);
  return node.top;
}

// 1. Cap prefix depth — nobody autocompletes on 40 characters.
const MAX_PREFIX = 20;   // beyond this, fall through to normal search

// 2. Store term IDs, not strings. 'apple' appears in the top list at
//    'a', 'ap', 'app', 'appl' — store 4-byte ids and resolve once.
