function suggestSafe(root, prefix, k = 5) {
  const node = findPrefix(root, prefix);
  if (!node) return [];

  return node.top                    // stored with k + margin
    .filter((e) => !blocklist.has(e.id))
    .slice(0, k)
    .map((e) => termsById[e.id]);
}

